[CmdletBinding()]
param([Parameter(Mandatory = $true)][string]$TestRoot)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$repoRoot = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..')).TrimEnd('\')
. (Join-Path $repoRoot 'src\core\TelephoneLine.Common.ps1')
. (Join-Path $repoRoot 'src\control-plane\TelephoneControlPlane.Common.ps1')
. (Join-Path $repoRoot 'src\supervisor\TelephoneSupervisor.Common.ps1')
. (Join-Path $repoRoot 'src\dashboard\TelephoneDashboard.Common.ps1')
. (Join-Path $repoRoot 'src\dashboard\TelephoneDashboard.Projection.ps1')

$assertions = 0
$testStartedAt=[DateTimeOffset]::UtcNow
function Assert-Control { param([bool]$Condition,[string]$Message) $script:assertions += 1; if(-not$Condition){throw $Message} }
function Write-ControlJson { param([string]$Path,$Value) $parent=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($Path));if(-not[IO.Directory]::Exists($parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};[IO.File]::WriteAllText($Path,(($Value|ConvertTo-Json -Depth 100).Replace("`r`n","`n")+"`n"),[Text.UTF8Encoding]::new($false)) }
function Write-ControlText { param([string]$Path,[string]$Text) $parent=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($Path));if(-not[IO.Directory]::Exists($parent)){[IO.Directory]::CreateDirectory($parent)|Out-Null};[IO.File]::WriteAllText($Path,$Text,[Text.UTF8Encoding]::new($false)) }
function Wait-ControlFile { param([string]$Path,[int]$Seconds=15) $until=[DateTimeOffset]::UtcNow.AddSeconds($Seconds);while([DateTimeOffset]::UtcNow-lt$until){if([IO.File]::Exists($Path)){return $true};Start-Sleep -Milliseconds 100};return $false }
function Wait-ControlCondition { param([scriptblock]$Condition,[int]$Seconds=15) $until=[DateTimeOffset]::UtcNow.AddSeconds($Seconds);while([DateTimeOffset]::UtcNow-lt$until){try{if(& $Condition){return $true}}catch{};Start-Sleep -Milliseconds 100};return $false }

$root=[IO.Path]::GetFullPath($TestRoot).TrimEnd('\');if([IO.Directory]::Exists($root)){throw'Control-plane test root must be new.'};[IO.Directory]::CreateDirectory($root)|Out-Null
$pwsh=[string]([Diagnostics.Process]::GetCurrentProcess().MainModule.FileName)
$authority=Join-Path $root 'AUTHORITY.md';Write-ControlText $authority "bounded control-plane authority`n"
$leadWorkspace=Join-Path $root 'lead-workspace';[IO.Directory]::CreateDirectory($leadWorkspace)|Out-Null
$leadBindingPath=Join-Path $root 'lead-binding.json';$session='11111111-2222-4333-8444-555555555555'
Write-ControlJson $leadBindingPath ([ordered]@{protocol_version='telephone-line-lead-binding-v1';session_id=$session;worktree=$leadWorkspace;launcher=[ordered]@{path=$pwsh;arguments=@('-NoLogo','-NoProfile','-NonInteractive','-Command','exit 0')}})
$leadOwnerPath=Join-Path $root 'lead-owner.json';$self=Get-Process -Id $PID;try{$leadOwner=[ordered]@{pid=[int]$PID;start_time_utc_ticks=[int64]$self.StartTime.ToUniversalTime().Ticks;started_at_utc=$self.StartTime.ToUniversalTime().ToString('o')}}finally{$self.Dispose()};Write-ControlJson $leadOwnerPath $leadOwner
$dashboardConfig=Join-Path $root 'dashboard\config.json';$supervisorState=Join-Path $root 'supervisor';[IO.Directory]::CreateDirectory($supervisorState)|Out-Null

function New-ControlActionScript {
    param([string]$Root,[string]$Name,[string]$Output,[string]$Text='done')
    $path=Join-Path $Root ($Name+'.ps1');$escaped=$Output.Replace("'","''");$value=$Text.Replace("'","''")
    Write-ControlText $path ("[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName('"+$escaped+"'))|Out-Null`n[IO.File]::AppendAllText('"+$escaped+"','"+$value+"`n',[Text.UTF8Encoding]::new(`$false))`n")
    return $path
}

function New-ControlWaveSpec {
    param(
        [string]$Name,[string]$Project,[string]$Epoch,[string]$Wave,[string]$ControlRoot,[int]$LaneCount=1,
        [object[]]$Actions=@(),[object]$Next=$null,[string]$BatchId=''
    )
    $fixture=Join-Path $root $Name;[IO.Directory]::CreateDirectory($fixture)|Out-Null
    if([string]::IsNullOrWhiteSpace($BatchId)){$BatchId=New-TelephoneControlPlaneDeterministicGuid -Seed ($Project+'|'+$Epoch+'|'+$Wave)}
    $routes=@('direct-grok-cli','direct-cursor','direct-codex-cli','direct-claude-code','direct-pi','deepsea-grok-cli')
    $lanes=[Collections.Generic.List[object]]::new()
    for($i=1;$i-le$LaneCount;$i++){
        $package='P'+$i;$workspace=Join-Path $fixture ('workspace-'+$package);[IO.Directory]::CreateDirectory($workspace)|Out-Null
        $output=Join-Path $workspace 'out\result.json';$task=New-ControlActionScript -Root $fixture -Name ('task-'+$package) -Output $output -Text $package
        [void]$lanes.Add([ordered]@{package_id=$package;stage=$package;summary=('bounded '+$package);role='execution';route=$routes[$i-1];line_job_id=(New-TelephoneControlPlaneDeterministicGuid -Seed ($Project+'|'+$Epoch+'|'+$Wave+'|'+$package));telephone_state_root=(Join-Path $fixture 'telephone-state');workspace=$workspace;card_text=($package+' bounded card');command=[ordered]@{executable=$pwsh;working_directory=$workspace;arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',$task)};allowed_write_paths=@('out/result.json');launch_grace_seconds=1;callback_grace_seconds=1})
    }
    if($null-eq$Next){$Next=[ordered]@{transition_id='manual';kind='manual';authorized=$false;idempotency_key=('manual:'+$Wave)}}
    $spec=[ordered]@{protocol_version='telephone-line-control-plane-wave-spec-v1';project=$Project;project_epoch=$Epoch;goal_summary=('bounded '+$Wave);authority_path=$authority;lead_binding_file=$leadBindingPath;wave_id=$Wave;batch_id=$BatchId;control_state_root=$ControlRoot;supervisor_state_root=$supervisorState;install_root=$repoRoot;dashboard_config_path=$dashboardConfig;projection_stale_after_seconds=5;lead=[ordered]@{transport='wired';session_id=$session;run_id=('lead-'+$Epoch);owner_file=$leadOwnerPath};next_transition=$Next;lanes=@($lanes.ToArray());actions=@($Actions)}
    $specPath=Join-Path $fixture 'wave-spec.json';Write-ControlJson $specPath $spec
    return [ordered]@{spec_path=$specPath;spec=$spec;fixture=$fixture;batch_id=$BatchId;lanes=@($lanes.ToArray())}
}

function Invoke-ControlBuild { param($Fixture,[switch]$Activate) $text=if($Activate){& (Join-Path $repoRoot 'src\control-plane\New-TelephoneWaveManifest.ps1') -SpecFile $Fixture.spec_path -Activate|Out-String}else{& (Join-Path $repoRoot 'src\control-plane\New-TelephoneWaveManifest.ps1') -SpecFile $Fixture.spec_path|Out-String};return($text|ConvertFrom-Json -AsHashtable -Depth 100 -DateKind String) }

function New-ManualControlJob {
    param([Collections.IDictionary]$Manifest,[Collections.IDictionary]$Lane,[ValidateSet('handled','stalled','dead_owner','qualified_start_failure','callback_loss','malformed_receipt','shared_host','after_prompt','after_result')][string]$Mode)
    $jobRoot=Join-Path (Join-Path ([string]$Lane.telephone_state_root)'jobs')([string]$Lane.line_job_id);[IO.Directory]::CreateDirectory($jobRoot)|Out-Null;$paths=Get-TelephoneJobPaths -JobRoot $jobRoot
    $requestRead=Read-TelephoneJson -Path ([string]$Lane.request.path);$request=$requestRead.value;$lead=Read-TelephoneLeadBinding -Lead $request.lead;$leadId=Write-TelephoneJsonCreateNew -Path $paths.lead_binding -Value $lead
    $dispatch=[ordered]@{protocol_version='telephone-line-dispatch-v1';line_job_id=[string]$request.line_job_id;project=[string]$request.project;stage=[string]$request.stage;role=[string]$request.role;route=[string]$request.route;summary=[string]$request.summary;lead=$lead;command=[ordered]@{executable=[string]$request.command.executable;working_directory=[string]$request.command.working_directory;arguments=@($request.command.arguments);stdin=$null};source_request=$requestRead.identity;lead_binding=$leadId;created_at_utc=[DateTimeOffset]::UtcNow.AddMinutes(-10).ToString('o');absolute_task_timeout=$false;project_judgment=$false;batch=$request.batch;control_plane=$request.control_plane}
    Write-ControlJson $paths.dispatch $dispatch
    if($Mode-in@('handled','dead_owner','qualified_start_failure','callback_loss','after_prompt','after_result')){Write-ControlJson $paths.command_start_intent ([ordered]@{protocol_version='telephone-line-command-start-v1';line_job_id=[string]$Lane.line_job_id;dispatch=(Get-TelephoneFileIdentity -Path $paths.dispatch);command_host=(Get-TelephoneFileIdentity -Path (Join-Path $repoRoot 'src\core\Invoke-TelephoneLineCommandHost.ps1'));created_at_utc=[DateTimeOffset]::UtcNow.AddMinutes(-10).ToString('o')})}
    if($Mode-eq'dead_owner'){Write-ControlJson $paths.command_owner ([ordered]@{pid=999999;start_time_utc_ticks=1;started_at_utc=[DateTimeOffset]::UtcNow.AddMinutes(-10).ToString('o')})}
    if($Mode-in@('handled','qualified_start_failure','callback_loss','after_result')){if($Mode-ne'qualified_start_failure'){[IO.File]::WriteAllBytes($paths.stdout,[byte[]]@());[IO.File]::WriteAllBytes($paths.stderr,[byte[]]@())};$dispatchRead=Read-TelephoneJson -Path $paths.dispatch -SchemaName 'dispatch';$receipt=if($Mode-eq'qualified_start_failure'){New-TelephoneTransportFailureReceipt -DispatchRead $dispatchRead -ErrorCode 'COMMAND_START_FAILED' -ErrorMessage (Get-TelephonePublicErrorMessage -ErrorCode 'COMMAND_START_FAILED') -StartedAtUtc $null}else{New-TelephoneCommandBoundReceipt -DispatchRead $dispatchRead -Paths $paths -ExitCode $(if($Mode-in@('handled','callback_loss')){0}else{1}) -StartedAtUtc ([DateTimeOffset]::UtcNow.AddMinutes(-10).ToString('o'))};Write-ControlJson $paths.receipt $receipt}
    if($Mode-eq'malformed_receipt'){Write-ControlText $paths.receipt '{broken'}
    if($Mode-eq'shared_host'){Write-ControlJson (Join-Path $jobRoot 'shared-host-failure.json') ([ordered]@{protocol_version='telephone-line-control-plane-shared-host-failure-v1';line_job_id=[string]$Lane.line_job_id;failure_class='shared_host';observed_at_utc=[DateTimeOffset]::UtcNow.ToString('o')})}
    if($Mode-eq'handled'){
        $delivery=[ordered]@{protocol_version='telephone-line-delivery-v1';line_job_id=[string]$Lane.line_job_id;lead_session_id=[string]$Manifest.lead.session_id;wake_run_id='fixture-wake';wake_key='fixture-key';lead_run_root=$leadWorkspace;launcher_state='completed';wake_acknowledgment=[ordered]@{acknowledged=$true};delivered_at_utc=[DateTimeOffset]::UtcNow.ToString('o')};$delivery=Add-TelephoneControlPlaneDeliveryBinding -Delivery $delivery -Dispatch $dispatch -JobPaths $paths;Write-ControlJson $paths.delivery $delivery
        $receiptIdentity=Get-TelephoneFileIdentity -Path $paths.receipt;$deliveryIdentity=Get-TelephoneFileIdentity -Path $paths.delivery
        $wavePaths=Get-TelephoneControlPlanePaths -ControlStateRoot ([string]$Manifest.control_state_root) -Project ([string]$Manifest.project) -ProjectEpoch ([string]$Manifest.project_epoch) -WaveId ([string]$Manifest.wave_id);$manifestIdentity=Get-TelephoneFileIdentity -Path ([string]$wavePaths.manifest);$attempt=Get-TelephoneControlPlaneLaneAttempt -Lane $Lane -WavePaths $wavePaths
        Write-ControlJson (Join-Path $jobRoot 'handled-by-lead.json') ([ordered]@{protocol_version='telephone-line-control-plane-handled-v1';line_job_id=[string]$Lane.line_job_id;lead_session_id=[string]$Manifest.lead.session_id;lead_run_id=[string]$Manifest.lead.run_id;manifest_sha256=[string]$manifestIdentity.sha256;receipt_sha256=[string]$receiptIdentity.sha256;delivery_sha256=[string]$deliveryIdentity.sha256;attempt=[int]$attempt.attempt;package_id=[string]$Lane.package_id;batch_id=[string]$dispatch.batch.batch_id;route=[string]$Lane.route;workspace=[string]$Lane.workspace;write_lease_id=[string]$Lane.write_lease_id;handled_at_utc=[DateTimeOffset]::UtcNow.ToString('o')})
    }
    if($Mode-eq'after_prompt'){Write-ControlText (Join-Path $jobRoot 'prompt-sent.marker') "prompt`n"}
    foreach($p in @($paths.dispatch,$paths.command_start_intent,$paths.command_owner,$paths.receipt,$paths.relay_owner,$paths.relay_error,(Join-Path $jobRoot 'prompt-sent.marker'))){if([IO.File]::Exists($p)){(Get-Item -LiteralPath $p).LastWriteTimeUtc=[DateTime]::UtcNow.AddMinutes(-10)}}
    return [ordered]@{root=$jobRoot;paths=$paths}
}

# 1. Zero, one and many action manifests remain arrays.
foreach ($count in @(0,1,3)) {
    $actions=[Collections.Generic.List[object]]::new();$prior=$null
    for ($i=1; $i -le $count; $i++) {$marker=Join-Path $root ("cardinality-$count-$i.marker");$script=New-ControlActionScript -Root $root -Name ("cardinality-$count-$i") -Output $marker;[void]$actions.Add([ordered]@{action_id=('a'+$i);kind='admission';sequence=$i;depends_on=[object[]]@($(if($null-eq$prior){}else{$prior}));idempotency_key=("cardinality:${count}:$i");trigger=$(if($null-eq$prior){[ordered]@{kind='always'}}else{[ordered]@{kind='file_exists';path=(Join-Path $root ("cardinality-$count-"+($i-1)+'.marker'))}});command=[ordered]@{executable=$pwsh;working_directory=$root;arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',$script)};expected_postcondition=[ordered]@{kind='file_exists';path=$marker};retry_policy='safe_once_if_no_effect'});$prior='a'+$i}
    $f=New-ControlWaveSpec -Name ("cardinality-$count") -Project("cardinality-$count") -Epoch 'e1' -Wave 'w1' -ControlRoot (Join-Path $root ("cardinality-$count-control")) -Actions @($actions.ToArray());$b=Invoke-ControlBuild $f;$m=(Read-TelephoneJson -Path ([string]$b.manifest.path) -SchemaName 'control-plane-wave-manifest').value
    Assert-Control(@($m.actions).Count-eq$count)("Action cardinality $count did not remain an array.")
}

# 2. Two consecutive waves retain immutable history, atomically move current, and no-op without rewriting.
$multiRoot=Join-Path $root 'multi-control';$w1=New-ControlWaveSpec -Name 'multi-w1' -Project 'multi-project' -Epoch 'e1' -Wave 'w1' -ControlRoot $multiRoot;$b1=Invoke-ControlBuild $w1   -Activate;$m1=[string]$b1.manifest.path;$s1=Update-TelephoneControlPlaneState -ManifestFile $m1
$w2=New-ControlWaveSpec -Name 'multi-w2' -Project 'multi-project' -Epoch 'e2' -Wave 'w2' -ControlRoot $multiRoot;$b2=Invoke-ControlBuild $w2   -Activate;$m2=[string]$b2.manifest.path;$s2=Update-TelephoneControlPlaneState -ManifestFile $m2
$history=(Read-TelephoneJson -Path ([string]$s2.paths.history) -SchemaName 'control-plane-history-index').value;$pointer=(Read-TelephoneJson -Path ([string]$s2.paths.pointer) -SchemaName 'control-plane-current-pointer').value
Assert-Control(@($history.waves).Count-eq2)'Two-wave history did not retain both immutable waves.';Assert-Control([string]$pointer.wave_id-ceq'w2')'Current pointer did not switch to wave two.';Assert-Control([IO.File]::Exists($m1)-and[IO.File]::Exists($m2))'Versioned wave manifests were not retained.'
$stable1=Update-TelephoneControlPlaneState -ManifestFile $m2;$stableIds=@((Get-TelephoneFileIdentity -Path ([string]$stable1.paths.current)).sha256,(Get-TelephoneFileIdentity -Path ([string]$stable1.paths.capsule)).sha256,(Get-TelephoneFileIdentity -Path ([string]$stable1.paths.history)).sha256);$stable2=Update-TelephoneControlPlaneState -ManifestFile $m2;$stableIds2=@((Get-TelephoneFileIdentity -Path ([string]$stable2.paths.current)).sha256,(Get-TelephoneFileIdentity -Path ([string]$stable2.paths.capsule)).sha256,(Get-TelephoneFileIdentity -Path ([string]$stable2.paths.history)).sha256)
Assert-Control(-not[bool]$stable2.changed-and(Get-TelephoneControlPlaneJsonFingerprint -Value $stableIds)-ceq(Get-TelephoneControlPlaneJsonFingerprint -Value $stableIds2))'Unchanged refresh rewrote a stable checkpoint.'

# 3. Current/capsule/history/event and pointer crash cuts reconstruct from immutable ledger/registration.
Write-ControlText ([string]$stable2.paths.current)'{broken';Write-ControlText ([string]$stable2.paths.capsule)'{broken';Write-ControlText ([string]$stable2.paths.history)'{broken';if([IO.File]::Exists([string]$stable2.paths.events)){[IO.File]::Delete([string]$stable2.paths.events)};$reconstructed=Update-TelephoneControlPlaneState -ManifestFile $m2
Assert-Control([string](Read-TelephoneJson -Path ([string]$reconstructed.paths.current) -SchemaName 'control-plane-current-state').value.wave_id-ceq'w2')'Ledger did not reconstruct current state.';Assert-Control([IO.File]::Exists([string]$reconstructed.paths.events))'Ledger did not reconstruct the event append cut.'
Write-ControlText ([string]$reconstructed.paths.pointer) '{broken';$wakeText=& (Join-Path $repoRoot 'src\control-plane\Invoke-TelephoneControlPlaneWake.ps1') -SupervisorStateRoot $supervisorState -InstallRoot $repoRoot | Out-String;$null=$wakeText|ConvertFrom-Json -Depth 64
Assert-Control([string](Read-TelephoneJson -Path ([string]$reconstructed.paths.pointer) -SchemaName 'control-plane-current-pointer').value.wave_id-ceq'w2')'Registration did not reconstruct the current pointer.'
$latestTransition=Get-ChildItem -LiteralPath ([string]$reconstructed.paths.ledger) -File | Sort-Object Name -Descending | Select-Object -First 1;Write-ControlText $latestTransition.FullName '{broken';Write-ControlText ([string]$reconstructed.paths.current) '{broken';$ledgerRepair=Update-TelephoneControlPlaneState -ManifestFile $m2
Assert-Control([IO.File]::Exists((Join-Path ([string]$ledgerRepair.paths.conflicts)'ledger-transition.json')))'Corrupt transition was not typed and isolated.';Assert-Control([string]$ledgerRepair.current.wave_id-ceq'w2')'Prior ledger transition did not converge back to the current wave.'
$ledgerMarkerPath=Join-Path ([string]$ledgerRepair.paths.conflicts)'ledger-transition.json';$ledgerMarker=(Read-TelephoneJson -Path $ledgerMarkerPath).value;Assert-Control([bool]$ledgerMarker.active-and@($ledgerRepair.current.findings)-contains'CONTROL_PLANE_LEDGER_CONFLICT')'Current corrupt ledger transition did not stay visibly yellow.';$quarantinePath=Join-Path ([string]$ledgerRepair.paths.conflicts)('quarantined-'+$latestTransition.Name+'.invalid');Move-Item -LiteralPath $latestTransition.FullName -Destination $quarantinePath;$ledgerResolved=Update-TelephoneControlPlaneState -ManifestFile $m2;$ledgerMarkerResolved=(Read-TelephoneJson -Path $ledgerMarkerPath).value;Assert-Control(-not[bool]$ledgerMarkerResolved.active-and@($ledgerResolved.current.findings)-notcontains'CONTROL_PLANE_LEDGER_CONFLICT')'Repaired ledger replay left a permanent historical yellow finding.';$ledgerGreen=@((Get-TelephoneDashboardProjection -ConfigPath $dashboardConfig).groups|Where-Object{[string]$_.project-ceq'multi-project'})[0];Assert-Control([string]$ledgerGreen.color-ceq'green')'Repaired ledger lineage did not return the HUD to current green truth.'

# 4. Stalled/dead/start-failed/callback-lost/malformed/shared-host evidence is honest and yellow.
$scenarioExpect=[ordered]@{stalled=@('executor_session','EXECUTOR_STALLED_AFTER_LAUNCH_GRACE',$false);dead_owner=@('executor_session','EXECUTOR_STALLED_AFTER_LAUNCH_GRACE',$false);qualified_start_failure=@('executor_session','EXECUTOR_OR_QUALIFIED_START_FAILURE',$false);callback_loss=@('telephone_transport','CALLBACK_LOST_AFTER_GRACE',$false);malformed_receipt=@('state_conflict','RECEIPT_INVALID',$true);shared_host=@('shared_host','SHARED_HOST_FAILURE',$true)}
foreach ($mode in $scenarioExpect.Keys) {$f=New-ControlWaveSpec -Name ('scenario-'+$mode) -Project('scenario-'+$mode) -Epoch 'e1' -Wave 'w1' -ControlRoot (Join-Path $root ('scenario-'+$mode+'-control'));$b=Invoke-ControlBuild $f   -Activate;$mr=Read-TelephoneJson -Path ([string]$b.manifest.path) -SchemaName 'control-plane-wave-manifest';$null=New-ManualControlJob -Manifest $mr.value -Lane $mr.value.lanes[0] -Mode $mode;$state=Update-TelephoneControlPlaneState -ManifestFile ([string]$mr.identity.path);$expected=$scenarioExpect[$mode];Assert-Control([string]$state.current.lanes[0].failure_class-ceq[string]$expected[0])("$mode failure class was dishonest.");Assert-Control([string]$state.current.lanes[0].diagnostic_code-ceq[string]$expected[1])("$mode diagnostic was dishonest.");Assert-Control([bool]$state.current.requires_pascal-eq[bool]$expected[2])("$mode Pascal boundary was wrong.")}
$projection=Get-TelephoneDashboardProjection -ConfigPath $dashboardConfig;$stalledRows=@($projection.groups|Where-Object{[string]$_.project-ceq'scenario-stalled'});Assert-Control($stalledRows.Count-eq1)'Stalled project was not uniquely registered in the HUD.';$stalledGroup=$stalledRows[0];Assert-Control([string]$stalledGroup.color-ceq'yellow')'Stalled dispatch still projected green.'
$stalePath=[string]$ledgerRepair.paths.current;$stale=(Read-TelephoneJson -Path $stalePath).value;$stale.updated_at_utc=[DateTimeOffset]::UtcNow.AddMinutes(-10).ToString('o');Write-ControlJson $stalePath $stale;$staleProjection=Get-TelephoneDashboardProjection -ConfigPath $dashboardConfig;$staleRows=@($staleProjection.groups|Where-Object{[string]$_.project-ceq'multi-project'});Assert-Control($staleRows.Count-eq1)'Multi-project HUD binding was not unique.';$staleGroup=$staleRows[0];Assert-Control([bool]$staleGroup.current_state_stale-and[string]$staleGroup.color-ceq'yellow')'Stale current projection was not exposed yellow.'

# 5. Exact-session admission -> second turn, crash completion, and safe single retry are identity-bound.
$actionRoot=Join-Path $root 'action-chain';[IO.Directory]::CreateDirectory($actionRoot)|Out-Null;$admissionMarker=Join-Path $actionRoot 'admission.marker';$secondMarker=Join-Path $actionRoot 'second.marker';$crashMarker=Join-Path $actionRoot 'crash.marker';$retryMarker=Join-Path $actionRoot 'retry.marker'
$admissionScript=New-ControlActionScript -Root $actionRoot -Name 'admission' -Output $admissionMarker;$secondScript=New-ControlActionScript -Root $actionRoot -Name 'second' -Output $secondMarker;$crashScript=New-ControlActionScript -Root $actionRoot -Name 'crash' -Output $crashMarker;$retryScript=New-ControlActionScript -Root $actionRoot -Name 'retry' -Output $retryMarker
$actions=@(
 [ordered]@{action_id='admission';kind='admission';sequence=1;depends_on=@();idempotency_key='admission:1';trigger=[ordered]@{kind='always'};command=[ordered]@{executable=$pwsh;working_directory=$actionRoot;arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',$admissionScript)};expected_postcondition=[ordered]@{kind='file_exists';path=$admissionMarker};retry_policy='safe_once_if_no_effect'},
 [ordered]@{action_id='second';kind='second_turn';sequence=2;depends_on=@('admission');idempotency_key='second:1';trigger=[ordered]@{kind='file_exists';path=$admissionMarker};command=[ordered]@{executable=$pwsh;working_directory=$actionRoot;arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',$secondScript)};expected_postcondition=[ordered]@{kind='file_exists';path=$secondMarker};retry_policy='safe_once_if_no_effect'},
 [ordered]@{action_id='crash-reconcile';kind='admission';sequence=3;depends_on=@('second');idempotency_key='crash:1';trigger=[ordered]@{kind='always'};command=[ordered]@{executable=$pwsh;working_directory=$actionRoot;arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',$crashScript)};expected_postcondition=[ordered]@{kind='file_exists';path=$crashMarker};retry_policy='safe_once_if_no_effect'},
 [ordered]@{action_id='safe-retry';kind='admission';sequence=4;depends_on=@('crash-reconcile');idempotency_key='retry:1';trigger=[ordered]@{kind='always'};command=[ordered]@{executable=$pwsh;working_directory=$actionRoot;arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',$retryScript)};expected_postcondition=[ordered]@{kind='file_exists';path=$retryMarker};retry_policy='safe_once_if_no_effect'} )
$af=New-ControlWaveSpec -Name 'action-fixture' -Project 'action-project' -Epoch 'e1' -Wave 'w1' -ControlRoot (Join-Path $root 'action-control') -Actions $actions;$ab=Invoke-ControlBuild $af   -Activate;$am=Read-TelephoneJson -Path ([string]$ab.manifest.path) -SchemaName 'control-plane-wave-manifest';$as=Update-TelephoneControlPlaneState -ManifestFile ([string]$am.identity.path)
