$heldMutexes=[Collections.Generic.List[string]]::new();foreach($stateRoot in @($supervisorState,[string]$timerManifest.value.supervisor_state_root,[string]$dirtyManifest.value.supervisor_state_root)|Sort-Object -Unique){$name=Get-TelephoneSupervisorMutexName -StateRoot $stateRoot;$created=$false;$mutex=[Threading.Mutex]::new($false,$name,[ref]$created);$acquired=$false;try{try{$acquired=$mutex.WaitOne(0)}catch [Threading.AbandonedMutexException]{$acquired=$true};if(-not$acquired){[void]$heldMutexes.Add($name)}}finally{if($acquired){try{[void]$mutex.ReleaseMutex()}catch{}};$mutex.Dispose()}}
